// Package server assembles the gateway HTTP handler: REST→gRPC routes generated by
// grpc-gateway, middleware, health endpoints and the OpenAPI spec.
package server

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"strings"
	"time"

	"github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
	"github.com/redis/go-redis/v9"
	"github.com/rs/cors"
	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
	"google.golang.org/protobuf/encoding/protojson"

	authv1 "github.com/Andas-LV/cargoflow/gen/go/auth/v1"
	notificationv1 "github.com/Andas-LV/cargoflow/gen/go/notification/v1"
	shipmentv1 "github.com/Andas-LV/cargoflow/gen/go/shipment/v1"
	trackingv1 "github.com/Andas-LV/cargoflow/gen/go/tracking/v1"
	"github.com/Andas-LV/cargoflow/gen/openapi"
	"github.com/Andas-LV/cargoflow/pkg/grpcx"
	"github.com/Andas-LV/cargoflow/pkg/health"
	"github.com/Andas-LV/cargoflow/pkg/redisx"
	"github.com/Andas-LV/cargoflow/services/gateway/internal/config"
	"github.com/Andas-LV/cargoflow/services/gateway/internal/middleware"
)

// Backends are client connections to the internal gRPC services.
type Backends struct {
	Auth, Shipment, Tracking, Notification *grpc.ClientConn
}

// New builds the gateway's HTTP server.
func New(ctx context.Context, cfg config.Config, b Backends, rdb *redis.Client, log *slog.Logger) (*http.Server, error) {
	gw := runtime.NewServeMux(
		runtime.WithIncomingHeaderMatcher(headerMatcher),
		runtime.WithMetadata(func(_ context.Context, r *http.Request) metadata.MD {
			if id, ok := middleware.UserID(r.Context()); ok {
				return metadata.Pairs(grpcx.UserIDKey, id)
			}
			return nil
		}),
		runtime.WithMarshalerOption(runtime.MIMEWildcard, &runtime.HTTPBodyMarshaler{
			Marshaler: &runtime.JSONPb{
				MarshalOptions:   protojson.MarshalOptions{EmitUnpopulated: true},
				UnmarshalOptions: protojson.UnmarshalOptions{DiscardUnknown: true},
			},
		}),
	)
	if err := authv1.RegisterAuthServiceHandler(ctx, gw, b.Auth); err != nil {
		return nil, fmt.Errorf("register auth routes: %w", err)
	}
	if err := shipmentv1.RegisterShipmentServiceHandler(ctx, gw, b.Shipment); err != nil {
		return nil, fmt.Errorf("register shipment routes: %w", err)
	}
	if err := trackingv1.RegisterTrackingServiceHandler(ctx, gw, b.Tracking); err != nil {
		return nil, fmt.Errorf("register tracking routes: %w", err)
	}
	if err := notificationv1.RegisterNotificationServiceHandler(ctx, gw, b.Notification); err != nil {
		return nil, fmt.Errorf("register notification routes: %w", err)
	}

	authClient := authv1.NewAuthServiceClient(b.Auth)
	api := chain(gw,
		middleware.RateLimit(rdb, cfg.RateLimitRequests, cfg.RateLimitWindow, log),
		middleware.Auth(tokenValidator{authClient}, isPublic),
	)

	root := http.NewServeMux()
	health.Register(root, health.Checks{
		"redis":        redisx.Check(rdb),
		"auth":         grpcx.HealthCheck(b.Auth),
		"shipment":     grpcx.HealthCheck(b.Shipment),
		"tracking":     grpcx.HealthCheck(b.Tracking),
		"notification": grpcx.HealthCheck(b.Notification),
	})
	root.HandleFunc("GET /openapi.json", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write(openapi.Spec)
	})
	root.Handle("/", api)

	corsHandler := cors.New(cors.Options{
		AllowedOrigins: cfg.CORSOrigins,
		AllowedMethods: []string{http.MethodGet, http.MethodPost, http.MethodPut, http.MethodPatch, http.MethodDelete},
		AllowedHeaders: []string{"Authorization", "Content-Type"},
		ExposedHeaders: []string{"X-RateLimit-Limit", "X-RateLimit-Remaining", "Retry-After"},
		MaxAge:         600,
	}).Handler

	handler := otelhttp.NewHandler(
		chain(root, corsHandler, middleware.Logging(log)),
		"gateway",
		otelhttp.WithSpanNameFormatter(func(_ string, r *http.Request) string {
			return r.Method + " " + r.URL.Path
		}),
	)

	return &http.Server{
		Addr:              cfg.HTTPAddr,
		Handler:           handler,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       60 * time.Second,
	}, nil
}

// chain wraps h with middlewares; the first one is the outermost.
func chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

// isPublic marks routes that work without a token.
func isPublic(r *http.Request) bool {
	return strings.HasPrefix(r.URL.Path, "/v1/auth/")
}

// headerMatcher is grpc-gateway's default matcher, except that clients cannot inject the
// trusted user identity via a "Grpc-Metadata-X-User-Id" header.
func headerMatcher(key string) (string, bool) {
	md, ok := runtime.DefaultHeaderMatcher(key)
	if ok && strings.EqualFold(md, grpcx.UserIDKey) {
		return "", false
	}
	return md, ok
}

type tokenValidator struct {
	client authv1.AuthServiceClient
}

func (v tokenValidator) ValidateToken(ctx context.Context, token string) (string, error) {
	resp, err := v.client.ValidateToken(ctx, &authv1.ValidateTokenRequest{AccessToken: token})
	if err != nil {
		return "", err
	}
	return resp.GetUserId(), nil
}
